package com.vandorlabs.neoforge.gear;
import java.util.*;import com.vandorlabs.neoforge.navigation.observer.*;import net.minecraft.core.BlockPos;import net.minecraft.server.level.*;import net.minecraft.world.level.block.state.BlockState;import net.neoforged.neoforge.event.level.BlockEvent;
/** Complete loaded observer closure; permission probes confer no world-write or mining admission. */
public final class NativeObserverCapture {
 private record Probe(BlockEvent.BreakEvent event,ServerLevel world,ServerPlayer actor){}private static final ThreadLocal<Probe> PROBE=new ThreadLocal<>();
 public static boolean isProbe(BlockEvent.BreakEvent event){var p=PROBE.get();return p!=null&&p.event==event&&event.getLevel()==p.world&&event.getPlayer()==p.actor;}
 static boolean breakBlocked(NativeGearEntity arm,ServerLevel world,BlockPos pos,BlockState state){var event=new BlockEvent.BreakEvent(world,pos,state,arm.actor());if(!(state.getBlock() instanceof NativeObserverCoreBlock)&&!(state.getBlock() instanceof NativeObserverPartBlock))return net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event).isCanceled();var previous=PROBE.get();PROBE.set(new Probe(event,world,arm.actor()));try{return net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event).isCanceled();}finally{if(previous==null)PROBE.remove();else PROBE.set(previous);}}
 static Set<BlockPos> complete(ServerLevel world,Set<BlockPos> selected){var roots=new LinkedHashSet<NativeObserverEntity>();for(var p:selected){if(!NativeObserverFormation.loaded(world,p))throw new IllegalArgumentException("Load the complete attachment before moving it");var state=world.getBlockState(p);if(!(state.getBlock() instanceof NativeObserverCoreBlock)&&!(state.getBlock() instanceof NativeObserverPartBlock))continue;var root=NativeObserverBindings.ownerAt(world,p);if(root==null||root.inert()||!root.available())throw new IllegalArgumentException("Load the complete observer before moving it");if(root.formed())roots.add(root);}if(roots.isEmpty())return selected;var result=new TreeSet<BlockPos>();result.addAll(selected);for(var root:roots){var d=root.design();for(int x=0;x<d.width();x++)for(int y=0;y<d.height();y++)for(int z=0;z<d.depth();z++){var p=root.cell(x,y,z);if(!NativeObserverAccess.member(root,p))throw new IllegalArgumentException("Load every owned observer member before moving it");result.add(p);if(result.size()>8192)throw new IllegalArgumentException("Observer attachment exceeds the arm cell budget");}}return Set.copyOf(result);}
 private NativeObserverCapture(){}
}
